DROP TABLE IF EXISTS `erp_input_event`;

CREATE TABLE erp_input_event (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `tenant_id` varchar(64) NOT NULL COMMENT '租户编码',
  `merchant_code` varchar(64) NOT NULL COMMENT '商家编码',
  `sharding_key` varchar(128) NOT NULL COMMENT '分库分表键',
  `out_biz_code` varchar(128) NOT NULL COMMENT '外部业务单号',
  `event_code` varchar(64) DEFAULT NULL COMMENT '内部事件编码',
  `unique_code` varchar(128) NOT NULL,
  `content` text DEFAULT NULL,
  `input_attributes` text,
  `attributes` text COMMENT '业务扩展字段',
  `error_code` varchar(64) DEFAULT NULL COMMENT '错误编码',
  `error_msg` text COMMENT '错误原因',
  `version` int(11) NOT NULL COMMENT '版本',
  `is_delete` tinyint(4) NOT NULL COMMENT '是否删除',
  `is_test` tinyint(4) NOT NULL COMMENT '是否测试',
  `process_node` varchar(64) NOT NULL COMMENT '过程节点',
  `status` int(11) NOT NULL COMMENT '状态',
  `env` varchar(32) NOT NULL COMMENT '环境',
  `industry_order_id` bigint(20) DEFAULT NULL COMMENT '行业单据id',
  `extend_query` varchar(256) DEFAULT NULL COMMENT '扩展查询',
  `biz_order_code` varchar(64) DEFAULT NULL COMMENT '业务单据编码'
)
;
